export default function  HeaderAutoHideResize ({toggleButtonGroups}) {
    const rootRef = useRef();
    const [buttons, setButtons] = useState(0);
    const [toggleButtonShows, toggleButtonHides] = useMemo(() => {
        return filterObjects();
    }, [toggleButtonGroups, ]);

  useLayoutEffect(() => {
    console.log(buttons);
    const handleResize = event => {
        const root = rootRef.current;
        if(root) {
            const width = parseFloat(window.getComputedStyle(root).width);
            const buttonGroups = toggleButtonGroups.map(buttons => buttons.children)?.flat().length;
            const currentButtonGroups = Math.floor(width / 42.5);

            console.log(buttonGroups);

            if(buttons !== currentButtonGroups)
                setButtons(currentButtonGroups);
            // console.log(width, buttons * 42.5);
        }
    }
    if(buttons === 0) handleResize();
    window.addEventListener('resize', handleResize);
    return () => {
        window.removeEventListener('resize', handleResize);
    };
  }, [toggleButtonGroups, buttons]);
  
  return (
    <CustomPaper
        ref={rootRef}
    >
        {toggleButtonGroups.map(({children, ...props}, index, {length})  => (
            <React.Fragment key={index}>
                <ToggleButtonGroup
                    {...props}
                    size="small"
                >{React.Children.toArray(children)}</ToggleButtonGroup>
                {length - 1 !== index &&
                <Divider flexItem orientation="vertical" sx={{ mx: 0.5, my: 1 }} />}
            </React.Fragment>
        ))}
        
    </CustomPaper>

  );
}

